"""Issue 12 patch (JSON download + query-aware filenames). Run from ~/theobroma."""
import base64, os, shutil, sys
REPO = os.path.expanduser("~/theobroma")
def d(s): return base64.b64decode(s).decode("utf-8")
EDITS = [
    ('app.py', d('QGFwcC5yb3V0ZSgiL2Rvd25sb2FkIikKZGVmIGRvd25sb2FkX3BhZ2UoKTo='), d(''), 'add _build_filename helper before download_page()'),
    ('app.py', d(''), d(''), 'add JSON format and query-aware filename to search-results download'),
    ('app.py', d(''), d(''), 'add download=true for JSON download in api_search()'),
    ('app.py', d(''), d(''), 'add JSON streaming branch to bulk download'),
    ('templates/help.html', d('R0VUIC9hcGkvZmlsdGVyX29wdGlvbnMgICAgICAgICAmbWRhc2g7IGF2YWlsYWJsZSBraW5nZG9tLCByZWdpb24sIHNvdXJjZSwgY2xhc3MgdmFsdWVz'), d(''), 'document JSON download in help.html'),
]

def main():
    contents = {}
    for path, old, new, desc in EDITS:
        full = os.path.join(REPO, path)
        if full not in contents:
            with open(full) as f: contents[full] = f.read()
        c = contents[full]
        n = c.count(old)
        if n != 1:
            print(f"FAIL [{desc}] in {path}: {n} matches")
            sys.exit(1)
        contents[full] = c.replace(old, new, 1)
        print(f"OK   [{desc}]")
    for full, body in contents.items():
        bk = full + ".pre-issue12"
        if not os.path.exists(bk):
            shutil.copy2(full, bk)
            print(f"  backup: {os.path.basename(bk)}")
        with open(full, "w") as f: f.write(body)
        print(f"  wrote:  {os.path.basename(full)}")
    print("Issue 12 patch applied.")

if __name__ == "__main__": main()